module adc_bit_decoder
   (bit_out,
    t_data,
    t_valid,
    clk);
  output bit_out;
  input [11:0]t_data;
  input t_valid;
  input clk;

  wire bit_out;
  wire bit_q_i_1_n_0;
  wire bit_q_i_2_n_0;
  wire bit_q_i_3_n_0;
  wire clk;
  wire [11:0]t_data;
  wire t_valid;

  LUT5 #(
    .INIT(32'hFFFCAAAA)) 
    bit_q_i_1
       (.I0(bit_out),
        .I1(t_data[10]),
        .I2(t_data[9]),
        .I3(bit_q_i_2_n_0),
        .I4(t_valid),
        .O(bit_q_i_1_n_0));
  LUT6 #(
    .INIT(64'hEFEEEEEEAAAAAAAA)) 
    bit_q_i_2
       (.I0(t_data[11]),
        .I1(t_data[7]),
        .I2(bit_q_i_3_n_0),
        .I3(t_data[4]),
        .I4(t_data[5]),
        .I5(t_data[8]),
        .O(bit_q_i_2_n_0));
  LUT5 #(
    .INIT(32'h55557FFF)) 
    bit_q_i_3
       (.I0(t_data[6]),
        .I1(t_data[0]),
        .I2(t_data[2]),
        .I3(t_data[1]),
        .I4(t_data[3]),
        .O(bit_q_i_3_n_0));
  FDRE #(
    .INIT(1'b0)) 
    bit_q_reg
       (.C(clk),
        .CE(1'b1),
        .D(bit_q_i_1_n_0),
        .Q(bit_out),
        .R(1'b0));
endmodule

